-- Book of Magic: Techno-Wizard vehicles and three Eylor vessels
-- 15 vehicle rows, with 27 locations and 5 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~112-book-of-magic-tw-vehicles-and-eylor-vessels.sql
--
-- Written by scripts/vessel-sql.mjs from 2 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('tw-seaside-hover-platform', 'Seaside Hover Platform', 'rifts', 'vehicle', 'One.', '4-7 passengers (small craft), 10-14 passengers (medium craft) or 20-30 passengers (large craft).', NULL, '40 mph (64 km) with a maximum altitude of 100 feet (30.5 m). TW versions can go 60 mph (96 km) and up to 10,000 feet (3048 m).', '30 mph (48 km).', NULL, NULL, 100, 1, NULL, 175000, '175,000 credits (liquid fuel), 350,000 credits (Techno-Wizard), or 1.3 million credits (nuclear). Up to a million credits more for special features and weapons. Luxury features raise the total price by 50-200%. Large craft cost 200% of the average price, moderate craft 150%; small craft go for list price.', 'Manufacturer: Atlantis (the book cites Splynn Dimensional Market p.178). Class: hover vehicle and boat rolled into one, built in small, medium and large sizes and with a liquid fuel, nuclear or Techno-Wizard engine. MAXIMUM RANGE: 300 miles (480 km) on liquid fuel; unlimited with a nuclear engine; with a TW engine one hour of flying per 10 P.P.E. (20 I.S.P.), or indefinitely along a ley line. No weapon is printed.', 'Rifts Book of Magic p.337'),
  ('tw-tech-flying-platform', 'Tech-Flying Platform', 'rifts', 'vehicle', 'One pilot.', 'Up to 10 passengers.', NULL, '40 mph (64 km); maximum altitude 3,000 feet (914 m).', NULL, NULL, NULL, 120, 1, NULL, 150000, '150,000 credits (liquid fuel), 250,000 credits (TW), 1.2 million credits (nuclear).', 'Manufacturer: Atlantis (the book cites Splynn Dimensional Market p.178). Class: personal transport; the heading is the plural, Tech-Flying Platforms. MAXIMUM RANGE: 300 miles (480 km) with liquid fuel; unlimited with a nuclear engine; one hour per 10 P.P.E. (20 I.S.P.) with a TW engine, unlimited along ley lines. No weapon is printed here; the optional weapon and defensive features on printed 336 are written for a platform like this one.', 'Rifts Book of Magic p.337'),
  ('tw-tk-flyer-classic', 'TK-Flyer "Classic"', 'rifts', 'vehicle', 'One pilot.', NULL, NULL, '220 mph (352 km) along ley lines. Maximum altitude 5,000 feet (1524 m). Only works at and along ley lines unless it also has a light engine. VTOL capable.', NULL, NULL, NULL, 125, 1, NULL, 60000, '60,000-100,000 credits, varying with size and perks. 30% have a conventional combustion engine for flight away from the ley line; add 25,000-50,000 credits for those.', 'A one or two man gyro-copter or glider propelled by magic and telekinesis, found throughout North America (the book cites Rifts Ultimate Edition p.136). Class: the TW equivalent of the hover cycle. P.P.E. COST: 136 to create; one point to activate and fly along ley lines. SPELLS NEEDED: Fly (15), Float in Air (5), Wind Rush (20), Levitation (5), Energy Field (10), Call Lightning (15), Telekinesis (10) and a number of secret incantations. MAXIMUM RANGE: indefinitely along ley lines; does not work away from them. BONUSES: +1 on initiative, +3 to dodge, +5% to piloting skill. No weapon is printed.', 'Rifts Book of Magic p.337'),
  ('tw-wing-board-crescent', 'Wing Board: Crescent', 'rifts', 'vehicle', 'One pilot.', NULL, NULL, '60 mph (96 km), double on a ley line. Maximum altitude 10,000 feet (3,049 m), double on a ley line. VTOL capable.', NULL, NULL, NULL, 160, 1, NULL, 350000, '350,000 credits.', 'Manufacturer: Tolkeen and others (the book cites Coalition Wars One p.78). Class: the TW equivalent of the hover cycle. P.P.E. COST: 430 to create, 5 to activate and fly indefinitely. SPELLS NEEDED: Fly Like the Eagle (20), Float in Air (5), Wind Rush (20), Levitation (5), Energy Field (10), Call Lightning (20), Telekinesis (8), Carpet of Adhesion (10), Armor of Ithan (10) and a number of secret incantations. UPKEEP (printed under Maximum Range): it must be recharged with 110 P.P.E. every four months, and takes nothing less than 110 at a time. Without the recharge speed and all bonuses are halved; after 8 months it loses all magical properties and bonuses, is -40% to pilot and works only as a high-tech hover cycle until restored with 110 P.P.E. BONUSES: +1 on initiative, +1 to strike, +1 to dodge, +10% to piloting skill. O.C.C. BONUSES, with a little training, in addition: +1 on initiative, +2 to dodge, +10% to piloting skill.', 'Rifts Book of Magic p.338'),
  ('tw-wing-board-turbo', 'Wing Board: Turbo', 'rifts', 'vehicle', 'One.', 'One rider in emergencies.', NULL, '120 mph (192 km), double on a ley line. Maximum altitude 10,000 feet (3,049 m), double on a ley line.', NULL, NULL, NULL, 130, 1, NULL, 160000, '160,000-200,000 credits.', 'Manufacturer: Tolkeen and others (the book cites Coalition Wars One p.76). Class: the TW equivalent of a hovercycle. P.P.E. COST: 395 to create, 5 to activate and fly indefinitely. SPELLS NEEDED TO CREATE: Fly Like the Eagle, Float in Air, Wind Rush, Levitation, Energy Field, Telekinesis, Carpet of Adhesion, Armor of Ithan and a number of secret incantations. UPKEEP (printed under Maximum Range): it must be recharged with 90 P.P.E. every four months, and takes nothing less than 90 at a time. Without the recharge speed and all bonuses are halved; after 8 months it loses all magical properties and bonuses, is -40% to pilot and works only as a high-tech hover cycle until restored with 90 P.P.E. BONUSES: +1 on initiative, +1 to strike, +2 to dodge, +5% to piloting skill. O.C.C. BONUSES, with a little training, in addition: +2 on initiative, +2 to dodge, +1 attack per melee, +10% to pilot skill. No weapon is printed.', 'Rifts Book of Magic p.338'),
  ('tw-wing-pack', 'Wing Pack (TW Jet Pack)', 'rifts', 'vehicle', 'One.', NULL, NULL, '90 mph (144 km), double on a ley line. Maximum altitude 10,000 feet (3,049 m), double on a ley line.', NULL, NULL, NULL, 110, 1, NULL, 150000, 'Market cost 150,000-180,000 credits. Fair availability. The cross-reference heading TW Jet Pack on printed 337 says good availability.', 'Looks something like a tech jet pack with small SAMAS-like wings. Class: the TW equivalent of a tech jet pack. P.P.E. COST: 35 to activate and fly for two hours; 370 to create. SPELLS NEEDED TO CREATE: Fly Like the Eagle, Float in Air, Wind Rush, Levitation, Energy Field, Telekinesis, Armor of Ithan and a number of secret incantations. MAXIMUM RANGE: approximately 90 miles per hour of flight. BONUSES: +1 to dodge. No weapon is printed.', 'Rifts Book of Magic p.337-338'),
  ('tw-hover-yacht', 'TW Hover Yacht', 'rifts', 'ship', 'Up to 10+ (small), 20+ (medium) or 30+ (large) people.', NULL, NULL, NULL, '150 mph (240 km). The book prints one maximum speed for this hover water craft and names no regime.', NULL, NULL, 200, 1, NULL, 100000, '100,000-160,000 credits (small, six-man boat); 250,000-600,000 credits (mid-sized, 20-person boat); one million credits (large, more than 20 people).', 'A Techno-Wizard hover water craft found throughout North America, built in small, medium and large sizes. P.P.E. COST: 350 to create. SPELLS NEEDED: Levitation (5), Float in Air (5), Wind Rush (20) and Energy Field (20). MAXIMUM RANGE: two hours per 20 P.P.E. points. No weapon is printed.', 'Rifts Book of Magic p.338'),
  ('tw-self-propelled-boat', 'TW Self-Propelled Boat', 'rifts', 'ship', 'Up to 20+ people.', NULL, NULL, NULL, '30 mph (48 km).', NULL, NULL, 200, 1, NULL, 30000, '30,000-40,000 credits (small, six-man boat); 50,000-75,000 credits (mid-sized, 20-person boat); 125,000 credits (large, more than 20 people).', 'Class: sail boat, driven by magic; found throughout North America and built in small, medium and large sizes. P.P.E. COST: 210 to create; 10 P.P.E. (20 I.S.P.) to activate. SPELLS NEEDED: Wind Rush (20), Energy Field (10) and a couple of secret incantations. MAXIMUM RANGE: three hours. No weapon is printed.', 'Rifts Book of Magic p.339'),
  ('tw-underwater-ley-line-flyer', 'TW Underwater Ley Line Flyer', 'rifts', 'vehicle', 'One.', NULL, NULL, NULL, 'Underwater 45 mph (72 km); maximum depth 400 feet (122 m).', NULL, NULL, 35, 1, NULL, 5000, '5,000-20,000 depending on the design and quality.', 'Class: underwater wing board. P.P.E. COST: 50 to create; 1 P.P.E. or 3 I.S.P. to activate. SPELLS NEEDED: Swim as the Fish (12) and a couple of other incantations. MAXIMUM RANGE: indefinitely so long as it is on a ley line; off a ley line it loses power. No weapon is printed.', 'Rifts Book of Magic p.339'),
  ('tw-underwater-scooter', 'TW Underwater Scooter', 'rifts', 'vehicle', 'One or two.', NULL, NULL, NULL, 'Underwater 60 mph (96 km); maximum depth 400 feet (122 m).', NULL, NULL, 75, 1, NULL, 50000, '50,000-75,000 credits (one-man scooter), 75,000-100,000 (two-man scooter). Add 25,000 credits for a conventional motor, 500,000 for a protective energy field (50 M.D.C.), 200,000 for a Breathe Without Air bubble.', 'Class: underwater jet ski. P.P.E. COST: 250 to create; 20 P.P.E. or 40 I.S.P. to activate. SPELLS NEEDED: Swim as the Fish, Energy Field, Wind Rush. MAXIMUM RANGE: six hours. No weapon is printed.', 'Rifts Book of Magic p.339'),
  ('tw-water-sled', 'TW Water Sled', 'rifts', 'vehicle', 'One or two.', NULL, NULL, NULL, 'Surface 100 mph (160 km).', NULL, NULL, 80, 1, NULL, 50000, '50,000 credits (one-man sled); 75,000 credits for a two-man sled.', 'Class: jet ski. P.P.E. COST: 270 to create; 20 P.P.E. to activate. SPELLS NEEDED: Swim as a Fish, Telekinesis, Energy Field. MAXIMUM RANGE: five hours. BONUSES: +1 to dodge, +5% to piloting skill, +10% to balance. No weapon is printed.', 'Rifts Book of Magic p.339'),
  ('tw-windjammer-frigate', 'Windjammer TW Frigate', 'rifts', 'ship', '63 total: captain and first mate (Warlock or Ley Line Walker O.C.C.), two navigators, three engineers, chief gunner, a medical officer (healer or priest), cook, three assistant cooks, 20 gunners and 30 additional seamen.', NULL, NULL, NULL, 'Sailing 16 mph (26 km); all oars 6 mph (9.6 km). Speed is doubled along ley lines.', 'Width 30 feet (9 m). Length 130 feet (40 m). Cargo: 100 tons.', '50 tons', 750, 1, NULL, 240000000, '240 million credits for a fully loaded ship WITHOUT the Dome of the Elements. Frigates are not sold with the Dome; the book says the price would rise to two billion credits if they were.', 'Model Type: Windjammer Class TW Sail Frigate (the book cites Sourcebook 4: Coalition Navy p.125). A three-masted wooden sailing warship with broadside cannons, built by hand at Queenston Harbor and used mostly by the Nuhr Dwarven pirates there, whose navy has nine by the end of the Coalition/Tolkeen War; four more, without the Dome, are to be offered for sale by spring 106 P.A. Ironwood magic turns its S.D.C. timber into Mega-Damage material, and it also carries Armor of Ithan and the equivalent of a simple protection circle that keeps lesser supernatural creatures off the ship unless their names are inscribed in it (automatic and constant). Suited to coastal defense and harbor protection; too slow for open water. POWER SYSTEM: natural wind power with magical back-up from the Dome of the Elements.', 'Rifts Book of Magic p.339-340'),
  ('splugorth-eylor-jet-pack', 'Splugorth "Eylor" Jet Pack', 'rifts', 'vehicle', 'One.', NULL, NULL, '120 mph (192 km), maximum altitude of 10,000 feet (3,048 m).', 'Underwater: 50 mph (80 km) with a maximum depth of one mile (1.6 km).', NULL, NULL, 120, 1, NULL, 40000000, '40 million credits. Rare outside Atlantis.', 'Manufacturer: Splugorth of Atlantis (the book cites Splynn Dimensional Market p.181). Class: personal jet pack with a living Haardeon organism built into it. ALIGNMENT: same as the user. HORROR FACTOR: 14. MAXIMUM RANGE: unlimited. BONUSES: +2 on initiative, +1 to strike, +4 to dodge, silent flight, +20% to piloting skill and trick maneuvers. OPTICS FROM THE EYE OF EYLOR, passed to the pilot constantly while the jet pack is attached: 1) perfect 20/20 vision and a wider color spectrum; 2) nightvision 600 feet (183 m); 3) telescopic vision 6000 feet (1830 m); 4) magnification to the 300th power; 5) polarized vision, and tells direction from the position of the sun at 88%; 6) psionic sensory perception - See Aura, See the Invisible, Sense Magic and see P.P.E. energy - with no added I.S.P. or P.P.E. MAGIC PROGRAM: Repel Animals (7), Turn Dead (6), Globe of Daylight (2), Lantern Light (1) and Fly Like the Eagle (25, castable if the flight system fails); all drawn from the Eye and cast by the pilot as a fifth level mage. AVAILABLE P.P.E.: 80 from the vehicle for the Magic Programs. HAARDEON PSIONICS: Detect Psionics, Nightvision, See the Invisible, Sense Evil, Sense Magic, Sense Time, Presence Sense and Mind Block.', 'Rifts Book of Magic p.316'),
  ('splugorth-eylor-hovercycle', 'Splugorth Eylor Hovercycle', 'rifts', 'vehicle', 'One (large).', NULL, NULL, '150 mph (240 km); double along ley lines. Max altitude 20,000 feet (6100 m).', 'No depth limitation underwater, same speed.', NULL, NULL, 200, 1, NULL, 20000000, '20 million credits. Rare outside of Atlantis.', 'Manufacturer: Splugorth of Atlantis (the book cites Splynn Dimensional Market p.182). Class: hovercycle. MAXIMUM RANGE: unlimited; functions in the air, in space, on the water and underwater. BONUSES: +2 on initiative, +2 to strike, +3 to dodge, +15% to piloting skill and trick maneuvers, and silent flight. OPTICS FROM THE EYE OF EYLOR, passed to the pilot constantly while riding the hovercycle: 1) perfect 20/20 vision and a wider color spectrum; 2) nightvision 600 feet (183 m); 3) telescopic vision 6000 feet (1830 m); 4) magnification to the 300th power; 5) polarized vision, and tells direction from the position of the sun at 88%; 6) psionic sensory perception - See Aura, See the Invisible, Sense Magic and see P.P.E. energy - with no added I.S.P. or P.P.E. MAGIC PROGRAM: Globe of Daylight (2), Magic Net (7), Fire Ball (10), Electric Arc (10), Call Lightning (15), Energy Disruption (12), Fire Ball (10) again as printed, Barrage (15), Ballistic Fire (25), Frequency Jamming (15) and Mystic Portal (60); all drawn from the Eye and cast by the pilot as a fifth level mage, but with double the usual range. AVAILABLE P.P.E.: 150 from the vehicle for the Magic Programs.', 'Rifts Book of Magic p.316'),
  ('splugorth-hover-platform', 'Splugorth Hover Platform', 'rifts', 'vehicle', 'One pilot.', 'One or two passengers.', NULL, 'Can hover stationary or fly at 53 mph (85 km), double along ley lines, and can attain a height of 2,400 feet (731 m).', 'No depth limitation underwater, same speed.', NULL, NULL, 300, 1, NULL, 50000000, '50 million credits. Rare outside of Atlantis.', 'Manufacturer: Splugorth of Atlantis (the book cites Splynn Dimensional Market p.180). Class: hover platform. MAXIMUM RANGE: unlimited. BONUSES: +2 on initiative, +1 to strike, +3 to dodge, +25% to piloting and trick maneuvers, and silent flight. OPTICS FROM THE EYE OF EYLOR, passed to the pilot constantly while flying the platform: 1) perfect 20/20 vision and a wider color spectrum; 2) nightvision 600 feet (183 m); 3) telescopic vision 6000 feet (1830 m); 4) magnification to the 300th power; 5) polarized vision, and tells direction from the position of the sun at 88%; 6) psionic sensory perception - See Aura, See the Invisible, Sense Magic and see P.P.E. energy - with no added I.S.P. or P.P.E. SENSORS: Track (humanoids) 70% and Track Animals 35%. MAGIC PROGRAM: Blinding Flash, Globe of Daylight, Fear and Befuddle, each castable by the pilot from the platform up to 200 feet (61 m) away. AVAILABLE P.P.E.: 50 from the vehicle for the Magic Programs. No weapon is printed.', 'Rifts Book of Magic p.316-317');

