INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('tw-wing-board-crescent', 1, 'Electrical Blaster', '4D6 M.D.', 1, '2,000 feet (610 m)', 'Equal to the number of attacks per melee round.', 'Two bolts per hour; the pilot can fire more by placing more P.P.E. into the board.', NULL, 'On a ley line increase range by 50% and add 1D6 M.D. to damage.'),
  ('tw-windjammer-frigate', 1, 'TK Thunderball Cannons (20)', 'Thunderball: 5D6 M.D. per cannon, or 5D6x10 M.D. for an entire broadside (10 guns). Thunderfire cannonball: 1D6x10 M.D., or 1D6x100 M.D. per broadside volley.', 1, '3000 feet (914 m)', 'Two shots per cannon, per melee round.', 'One per cannon; requires manual reloading. 200 additional Thunderballs are stored aboard under normal conditions, and 100 Thunderfire cannonballs are also carried for aggressive combat operations.', NULL, 'Primary weapon system. Techno-Wizard versions of muzzle-loading cast iron cannons that hurl the ball by telekinesis instead of gunpowder.'),
  ('tw-windjammer-frigate', 2, 'Dome of the Elements', 'By spell.', 0, 'By spell, cast as a 15th level caster.', 'Elemental summoning twice per 24 hours; it takes 1D6 melee rounds and has a 75% chance of success.', '1,000 P.P.E., regenerating 100 points per day; instantly and completely recharged at a ley line nexus or stone pyramid.', 'Captain and first mate within 1000 feet (305 m) of the Dome: +30 S.D.C. (M.D.C. for Mega-Damage creatures), +2 to save vs magic and psionics, +4 to save vs Horror Factor, immune to possession.', 'A basketball-sized Mega-Damage crystal mystically linked to the captain and first mate, who must be Warlocks or Ley Line Walkers; only they can draw on its P.P.E. A slain officer is replaced through a ritual by the Warlock who makes the Domes. SPELL MAGIC: Anti-Magic Cloud (140), Invisibility: Superior (100; masks the entire ship), Repel Animals (7), See the Invisible (4), Speed of the Snail (50), Summon and Control Storm (300), Sonar Hearing (10), Water Wall (25), Impervious to Fire (5). ELEMENTAL MAGIC: Change Wind Direction (6), Wind Rush (10), Calm Storm (20), Atmosphere Manipulation (50), Create Fog (5), Calm Waters (15), Whirlpool (40). ELEMENTAL CONTROL: summons Major Air or Water Elementals, which obey the captain or first mate as a 15th level Warlock.'),
  ('splugorth-eylor-jet-pack', 1, 'Haardeon Eye Beams', '4D6 M.D.', 1, '1,000 feet (305 m)', 'Three attacks per melee.', NULL, NULL, NULL),
  ('splugorth-eylor-hovercycle', 1, 'Forward Blasters (2)', '4D6 M.D. per single blast, 1D4x10+6 per simultaneous dual blast.', 1, '2,000 feet (610 m)', 'Equal to the number of attacks per melee round.', 'Unlimited.', NULL, NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 15 machines are in' AS assertion, count(*) AS got, 15 AS want
  FROM vehicles WHERE slug IN ('tw-seaside-hover-platform', 'tw-tech-flying-platform', 'tw-tk-flyer-classic', 'tw-wing-board-crescent', 'tw-wing-board-turbo', 'tw-wing-pack', 'tw-hover-yacht', 'tw-self-propelled-boat', 'tw-underwater-ley-line-flyer', 'tw-underwater-scooter', 'tw-water-sled', 'tw-windjammer-frigate', 'splugorth-eylor-jet-pack', 'splugorth-eylor-hovercycle', 'splugorth-hover-platform');
SELECT 'their 27 locations are in' AS assertion, count(*) AS got, 27 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('tw-seaside-hover-platform', 'tw-tech-flying-platform', 'tw-tk-flyer-classic', 'tw-wing-board-crescent', 'tw-wing-board-turbo', 'tw-wing-pack', 'tw-hover-yacht', 'tw-self-propelled-boat', 'tw-underwater-ley-line-flyer', 'tw-underwater-scooter', 'tw-water-sled', 'tw-windjammer-frigate', 'splugorth-eylor-jet-pack', 'splugorth-eylor-hovercycle', 'splugorth-hover-platform');
SELECT 'their 5 weapon entries are in' AS assertion, count(*) AS got, 5 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('tw-seaside-hover-platform', 'tw-tech-flying-platform', 'tw-tk-flyer-classic', 'tw-wing-board-crescent', 'tw-wing-board-turbo', 'tw-wing-pack', 'tw-hover-yacht', 'tw-self-propelled-boat', 'tw-underwater-ley-line-flyer', 'tw-underwater-scooter', 'tw-water-sled', 'tw-windjammer-frigate', 'splugorth-eylor-jet-pack', 'splugorth-eylor-hovercycle', 'splugorth-hover-platform');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('tw-seaside-hover-platform', 'tw-tech-flying-platform', 'tw-tk-flyer-classic', 'tw-wing-board-crescent', 'tw-wing-board-turbo', 'tw-wing-pack', 'tw-hover-yacht', 'tw-self-propelled-boat', 'tw-underwater-ley-line-flyer', 'tw-underwater-scooter', 'tw-water-sled', 'tw-windjammer-frigate', 'splugorth-eylor-jet-pack', 'splugorth-eylor-hovercycle', 'splugorth-hover-platform') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

